using System.Text.Json;using RouterStudio.Core.Contracts;using RouterStudio.Core.Services;
namespace RouterStudio.Core.Tests;
[TestClass] public sealed class HistoryStoreTests {
 private string root=null!;private readonly DateTimeOffset now=new(2026,10,6,0,0,0,TimeSpan.Zero);
 [TestInitialize]public void Setup()=>root=Path.Combine(Path.GetTempPath(),"Studio history Ω "+Guid.NewGuid().ToString("N"));
 [TestCleanup]public void Cleanup(){if(Directory.Exists(root))Directory.Delete(root,true);}
 private ProbeResult Result(DateTimeOffset? time=null)=>new(ProbeKind.Stream,"raw","PRO","8stoken",ProbeOutcome.Passed,null,200,2,1,time??now,new string('a',64));
 [TestMethod] public void RetentionDropsExpiredAndOver200(){var store=new HistoryStore(root,()=>now);store.AppendProbe(Result(now.AddDays(-31)));for(int i=0;i<205;i++)store.AppendProbe(Result(now.AddSeconds(-i)));Assert.AreEqual(200,store.Read().Count);Assert.IsTrue(store.Read().All(row=>row.AtUtc>=now.AddDays(-30)));}
 [TestMethod] public void CorruptHistoryDoesNotBlockAppAndAtomicWriteRecovers(){var store=new HistoryStore(root,()=>now);store.AppendProbe(Result());store.AppendAction("official",true,new string('a',64));File.WriteAllText(Path.Combine(root,"history.json"),"{broken");File.WriteAllText(Path.Combine(root,"history.json.tmp"),"partial");Assert.IsTrue(store.Read().Count>0);Assert.IsNotNull(store.Notice);store.AppendAction("router",true,new string('a',64));Assert.IsTrue(store.Read().Any(row=>row.Action=="router"));store.Clear();Assert.AreEqual(0,store.Read().Count);}
 [TestMethod] public void DigestMismatchIsStaleAndExportContainsNoRawFieldsPathsOrCanary(){var store=new HistoryStore(root,()=>now);store.AppendProbe(Result());var text=File.ReadAllText(Path.Combine(root,"history.json"));text=text.Replace("\"kind\":", "\"rawBody\":\"fake-non-sk-canary-secret\",\"kind\":");File.WriteAllText(Path.Combine(root,"history.json"),text);var export=store.Export(new(){SnapshotDigest=new string('b',64),RuntimeVersions=new(){Node="fake-non-sk-canary-secret",PowerShell="7.6.0"}});Assert.IsFalse(export.Contains("fake-non-sk-canary-secret"));Assert.IsFalse(export.Contains(root));using var doc=JsonDocument.Parse(export);Assert.IsTrue(doc.RootElement.GetProperty("activities")[0].GetProperty("stale").GetBoolean());}
 [TestMethod] public void ControlCharactersAndInvalidEnumsCannotPersist(){var store=new HistoryStore(root,()=>now);store.AppendProbe(Result() with {ModelId="raw\n<script>"});store.AppendAction("fake-canary-secret",false,new string('a',64));Assert.AreEqual(0,store.Read().Count);store.AppendProbe(Result() with {Outcome=(ProbeOutcome)999});Assert.AreEqual(0,store.Read().Count);}
 [TestMethod] public void NullHistoryRowsCannotCrashSupportExport(){Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"history.json"),"[null]");var store=new HistoryStore(root,()=>now);Assert.AreEqual(0,store.Read().Count);using var doc=JsonDocument.Parse(store.Export(null));Assert.AreEqual(0,doc.RootElement.GetProperty("activities").GetArrayLength());}
}
